concepts.code:
-- Racy: both sessions can see 0 rows, then both insert
SELECT 1 FROM users WHERE email = 'ana@shop.io';
-- app: if no row came back...
INSERT INTO users (email) VALUES ('ana@shop.io');

-- Atomic: the unique index decides, the loser just skips
INSERT INTO users (email) VALUES ('ana@shop.io')
ON CONFLICT (email) DO NOTHING;

CREATE TABLE stock (
  sku text PRIMARY KEY,
  qty int  NOT NULL
);
INSERT INTO stock VALUES ('MUG-1', 5);

INSERT INTO stock AS s (sku, qty)
VALUES ('MUG-1', 2), ('TEE-1', 4)
ON CONFLICT (sku) DO UPDATE
SET qty = s.qty + EXCLUDED.qty   -- stored + proposed
RETURNING sku, qty;
-- MUG-1 | 7
-- TEE-1 | 4

-- Live emails are unique; soft-deleted rows do not count
CREATE TABLE accounts (
  id      int GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  email   text NOT NULL,
  deleted boolean NOT NULL DEFAULT false
);
CREATE UNIQUE INDEX accounts_live_email
  ON accounts (lower(email)) WHERE NOT deleted;

INSERT INTO accounts (email) VALUES ('Ana@Shop.io')
ON CONFLICT (lower(email)) WHERE NOT deleted DO NOTHING;

-- Fails: the expression and predicate must match an index
-- INSERT ... ON CONFLICT (email) DO NOTHING;
-- ERROR: there is no unique or exclusion constraint matching the ON CONFLICT specification

