CREATE TEMP TABLE tags (k int PRIMARY KEY, v text);
INSERT INTO tags VALUES (1, 'a');
INSERT INTO tags VALUES (1, 'b'), (2, 'c')
ON CONFLICT (k) DO NOTHING
RETURNING k, v;

CREATE TEMP TABLE hits (k int PRIMARY KEY, n int);
INSERT INTO hits VALUES (1, 1), (1, 2)
ON CONFLICT (k) DO UPDATE SET n = hits.n + EXCLUDED.n;
SELECT k, n FROM hits;

CREATE TEMP TABLE subs (
  id int GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  email text UNIQUE
);
INSERT INTO subs (email) VALUES ('a@x.io');
INSERT INTO subs (email) VALUES ('a@x.io') ON CONFLICT DO NOTHING;
INSERT INTO subs (email) VALUES ('b@x.io');
SELECT id, email FROM subs ORDER BY id;

CREATE TEMP TABLE stock (sku text PRIMARY KEY, qty int);
INSERT INTO stock VALUES ('A', 5);
INSERT INTO stock VALUES ('A', 2)
ON CONFLICT (sku) DO UPDATE SET qty = qty + EXCLUDED.qty
RETURNING qty;

CREATE TEMP TABLE prices (sku text PRIMARY KEY, price int, ver int);
INSERT INTO prices VALUES ('A', 10, 5);
INSERT INTO prices VALUES ('A', 12, 3)
ON CONFLICT (sku) DO UPDATE
SET price = EXCLUDED.price, ver = EXCLUDED.ver
WHERE prices.ver < EXCLUDED.ver
RETURNING sku, price;

CREATE TEMP TABLE users (id int PRIMARY KEY, email text);
CREATE INDEX ON users (email);
INSERT INTO users VALUES (1, 'a@x.io')
ON CONFLICT (email) DO NOTHING;

CREATE TEMP TABLE t (k int PRIMARY KEY, n int);
INSERT INTO t VALUES (1, 5);
WITH m AS (
  MERGE INTO t
  USING (VALUES (3, 4), (1, 2)) AS s(k, n) ON t.k = s.k
  WHEN MATCHED THEN UPDATE SET n = t.n + s.n
  WHEN NOT MATCHED THEN INSERT VALUES (s.k, s.n)
  RETURNING merge_action() AS action, t.k, t.n
)
SELECT action, k, n FROM m ORDER BY k;
